function calculatePerformanceRating(stats, baselineStats) {
  if (stats.length === 0) {
    let baselineGoals = 0, baselineAssists = 0;
    for (const bs of baselineStats) {
      baselineGoals = Math.max(baselineGoals, bs.goals || 0);
      baselineAssists = Math.max(baselineAssists, bs.assists || 0);
    }
    if (baselineGoals + baselineAssists > 0) {
      return { rating: 50 };
    }
    return { rating: 50 };
  }
  const trackedGames = stats.length;
  const trackedWins = stats.filter((s) => s.won === true).length;
  const trackedGoals = stats.reduce((sum, s) => sum + (s.goals || 0), 0);
  const trackedAssists = stats.reduce((sum, s) => sum + (s.assists || 0), 0);
  const trackedTackles = stats.reduce((sum, s) => sum + (s.tackles || 0), 0);
  const trackedInterceptions = stats.reduce((sum, s) => sum + (s.interceptions || 0), 0);
  const trackedClearances = stats.reduce((sum, s) => sum + (s.clearances || 0), 0);
  const trackedCleanSheets = stats.filter((s) => s.clean_sheet === true).length;
  const trackedTackleSuccess = stats.reduce((sum, s) => sum + (s.tackle_success || 0), 0);
  const trackedDefensiveActions = stats.reduce((sum, s) => sum + (s.defensive_actions || 0), 0);
  const trackedSaves = stats.reduce((sum, s) => sum + (s.saves || 0) + (s.saves_diving || 0) + (s.saves_reflex || 0) + (s.saves_parry || 0) + (s.saves_cross || 0) + (s.saves_punch || 0), 0);
  const trackedGoalsConceded = stats.reduce((sum, s) => sum + (s.goals_conceded || 0), 0);
  const trackedGkClaims = stats.reduce((sum, s) => sum + (s.gk_claims || 0), 0);
  const trackedShots = stats.reduce((sum, s) => sum + (s.shots || 0), 0);
  const trackedShotsOnTarget = stats.reduce((sum, s) => sum + (s.shots_on_target || 0), 0);
  const trackedGoalsInsideBox = stats.reduce((sum, s) => sum + (s.goals_inside_box || 0), 0);
  const trackedPassesMade = stats.reduce((sum, s) => sum + (s.passes_made || 0), 0);
  const trackedPassesCompleted = stats.reduce((sum, s) => sum + (s.passes_completed || 0), 0);
  const trackedThroughBalls = stats.reduce((sum, s) => sum + (s.through_balls || 0), 0);
  const trackedProgressiveCarries = stats.reduce((sum, s) => sum + (s.progressive_carries || 0), 0);
  const trackedTouchesInBox = stats.reduce((sum, s) => sum + (s.touches_in_box || 0), 0);
  const trackedPressingActions = stats.reduce((sum, s) => sum + (s.pressing_actions || 0), 0);
  const trackedDribbleSuccess = stats.reduce((sum, s) => sum + (s.dribble_success || 0), 0);
  const trackedBigChances = stats.reduce((sum, s) => sum + (s.big_chances || 0), 0);
  const trackedForwardRuns = stats.reduce((sum, s) => sum + (s.forward_runs || 0), 0);
  const trackedOffensiveDuels = stats.reduce((sum, s) => sum + (s.offensive_duels || 0), 0);
  const trackedDefensiveDuels = stats.reduce((sum, s) => sum + (s.defensive_duels || 0), 0);
  const positionCounts = {};
  for (const s of stats) {
    const pos = s.position_played?.toUpperCase() || "";
    if (pos) {
      positionCounts[pos] = (positionCounts[pos] || 0) + 1;
    }
  }
  const primaryPosition = Object.keys(positionCounts).sort((a, b) => positionCounts[b] - positionCounts[a])[0] || "";
  const isGK = primaryPosition === "GK";
  const isDefender = ["CB", "LB", "RB", "LWB", "RWB", "SW"].includes(primaryPosition);
  const isMidfielder = ["CDM", "CM", "LM", "RM", "CAM", "LCM", "RCM", "LDM", "RDM"].includes(primaryPosition);
  const winRate = trackedGames > 0 ? trackedWins / trackedGames * 100 : 50;
  const avgGoals = trackedGames > 0 ? trackedGoals / trackedGames : 0;
  const avgAssists = trackedGames > 0 ? trackedAssists / trackedGames : 0;
  const avgTackles = trackedGames > 0 ? trackedTackles / trackedGames : 0;
  const avgInterceptions = trackedGames > 0 ? trackedInterceptions / trackedGames : 0;
  const avgClearances = trackedGames > 0 ? trackedClearances / trackedGames : 0;
  const avgSaves = trackedGames > 0 ? trackedSaves / trackedGames : 0;
  const cleanSheetRate = trackedGames > 0 ? trackedCleanSheets / trackedGames * 100 : 0;
  const avgGoalsConceded = trackedGames > 0 ? trackedGoalsConceded / trackedGames : 0;
  const shotAccuracy = trackedShots > 0 ? trackedShotsOnTarget / trackedShots * 100 : 50;
  const passAccuracy = trackedPassesMade > 0 ? trackedPassesCompleted / trackedPassesMade * 100 : 50;
  const tackleSuccessRate = trackedTackles > 0 ? trackedTackleSuccess / trackedTackles * 100 : 50;
  const avgGkClaims = trackedGames > 0 ? trackedGkClaims / trackedGames : 0;
  const avgThroughBalls = trackedGames > 0 ? trackedThroughBalls / trackedGames : 0;
  const avgProgressiveCarries = trackedGames > 0 ? trackedProgressiveCarries / trackedGames : 0;
  const avgTouchesInBox = trackedGames > 0 ? trackedTouchesInBox / trackedGames : 0;
  const avgPressingActions = trackedGames > 0 ? trackedPressingActions / trackedGames : 0;
  const avgDribbleSuccess = trackedGames > 0 ? trackedDribbleSuccess / trackedGames : 0;
  const avgBigChances = trackedGames > 0 ? trackedBigChances / trackedGames : 0;
  const avgForwardRuns = trackedGames > 0 ? trackedForwardRuns / trackedGames : 0;
  const gamesWithRating = stats.filter((s) => s.ea_match_rating !== null && s.ea_match_rating > 0);
  const avgEARating = gamesWithRating.length > 0 ? gamesWithRating.reduce((sum, s) => sum + s.ea_match_rating, 0) / gamesWithRating.length : null;
  const EA_RATING_MULTIPLIERS = {
    GK: 1.15,
    // Hardest to get high ratings - 15% boost
    DEFENDER: 1.1,
    // Hard to get high ratings - 10% boost
    MIDFIELDER: 1,
    // Baseline - no adjustment
    FORWARD: 0.9
    // Easiest to get high ratings - 10% reduction
  };
  const getPositionMultiplier = () => {
    if (isGK) return EA_RATING_MULTIPLIERS.GK;
    if (isDefender) return EA_RATING_MULTIPLIERS.DEFENDER;
    if (isMidfielder) return EA_RATING_MULTIPLIERS.MIDFIELDER;
    return EA_RATING_MULTIPLIERS.FORWARD;
  };
  const positionMultiplier = getPositionMultiplier();
  const normalizedEARating = avgEARating !== null ? Math.min(10, avgEARating * positionMultiplier) : null;
  let performanceRating;
  if (isGK) {
    performanceRating = winRate * 0.2;
    const savesContribution = Math.min(100, avgSaves * 20);
    performanceRating += savesContribution * 0.15;
    performanceRating += cleanSheetRate * 0.15;
    const claimsContribution = Math.min(100, avgGkClaims * 33);
    performanceRating += claimsContribution * 0.1;
    if (normalizedEARating !== null) {
      performanceRating += normalizedEARating * 10 * 0.4;
    } else {
      const gcPenalty = Math.max(0, 100 - avgGoalsConceded * 30);
      performanceRating += (cleanSheetRate * 0.5 + gcPenalty * 0.5) * 0.4;
    }
  } else if (isDefender) {
    performanceRating = winRate * 0.15;
    const tacklesContribution = Math.min(100, avgTackles * 20);
    performanceRating += tacklesContribution * 0.2;
    performanceRating += tackleSuccessRate * 0.1;
    const gaPerGameScore = Math.max(0, 100 - avgGoalsConceded * 33.33);
    performanceRating += gaPerGameScore * 0.15;
    performanceRating += cleanSheetRate * 0.2;
    const interceptionsContribution = Math.min(100, avgInterceptions * 25);
    performanceRating += interceptionsContribution * 0.05;
    const DEFENSIVE_POSITIONS = ["CB", "LB", "RB", "LWB", "RWB", "SW", "LCB", "RCB"];
    let defensiveGoals = 0, defensiveAssists = 0;
    for (const s of stats) {
      const pos = (s.position_played || "").toUpperCase();
      if (DEFENSIVE_POSITIONS.includes(pos)) {
        defensiveGoals += s.goals || 0;
        defensiveAssists += s.assists || 0;
      }
    }
    const defensiveGAPerGame = trackedGames > 0 ? (defensiveGoals + defensiveAssists) / trackedGames : 0;
    const defGAContribution = Math.min(100, defensiveGAPerGame * 100);
    performanceRating += defGAContribution * 0.05;
    if (normalizedEARating !== null) {
      performanceRating += normalizedEARating * 10 * 0.1;
    } else {
      performanceRating += (tacklesContribution * 0.5 + gaPerGameScore * 0.5) * 0.1;
    }
  } else if (isMidfielder) {
    performanceRating = winRate * 0.3;
    const gaContribution = Math.min(100, (avgGoals + avgAssists) * 50);
    performanceRating += gaContribution * 0.2;
    const defensiveContribution = Math.min(100, avgTackles * 12 + avgInterceptions * 15);
    performanceRating += defensiveContribution * 0.15;
    performanceRating += passAccuracy * 0.1;
    performanceRating += cleanSheetRate * 0.1;
    const interceptionsContribution = Math.min(100, avgInterceptions * 20);
    performanceRating += interceptionsContribution * 0.05;
    if (normalizedEARating !== null) {
      performanceRating += normalizedEARating * 10 * 0.1;
    } else {
      performanceRating += winRate * 0.1;
    }
  } else {
    performanceRating = winRate * 0.4;
    const gaContribution = Math.min(100, (avgGoals + avgAssists) * 50);
    performanceRating += gaContribution * 0.25;
    performanceRating += shotAccuracy * 0.15;
    if (normalizedEARating !== null) {
      performanceRating += normalizedEARating * 10 * 0.2;
    } else {
      performanceRating += winRate * 0.2;
    }
  }
  return { rating: Math.max(0, Math.min(100, performanceRating)) };
}
